# middleware.py
from functools import wraps
from flask import request, g
import jwt

def tenant_middleware(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header:
            return {"error": "Unauthorized"}, 401
        try:
            token = auth_header.split(" ")[1]
            payload = jwt.decode(token, 'SECRET_KEY', algorithms=['HS256'])
            g.tenant_id = payload['tenant_id']
        except:
            return {"error": "Invalid token"}, 401
        return func(*args, **kwargs)
    return wrapper

def zero_trust_middleware(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        mtl_token = request.headers.get('X-MTLS-TOKEN')
        if not mtl_token:
            return {"error": "mTLS required"}, 403
        # Simulated mTLS validation
        if mtl_token != 'VALID_MTLS_TOKEN':
            return {"error": "Invalid mTLS token"}, 403
        return func(*args, **kwargs)
    return wrapper

