# legal_brain_versioning.py
from models import ModelVersion

class LegalBrainVersionControl:
    def __init__(self):
        self.model_registry = {
            'legal_classifier': {
                'latest': 'v2.1',
                'versions': ['v1.0', 'v1.5', 'v2.0', 'v2.1']
            }
        }
    
    def register_model_version(self, model_type, version, metadata):
        if model_type not in self.model_registry:
            self.model_registry[model_type] = {'versions': []}
        
        self.model_registry[model_type]['versions'].append(version)
        self.model_registry[model_type]['latest'] = version
        
        model_version = ModelVersion(
            version=version,
            model_type=model_type,
            metadata=metadata
        )
        db.session.add(model_version)
        db.session.commit()
        return model_version

